Solution: The following algorithm can be used to schedule the meetings:

1. Sort the persons based on their availability.
2. Iterate through the sorted list and find the earliest available time slot for each person.
3. If the person's meeting duration is less than or equal to the remaining time in the time slot, schedule the meeting.
4. If the person's meeting duration is greater than the remaining time in the time slot, schedule the meeting for the next available time slot.
5. Repeat steps 2-4 until all the meetings have been scheduled.

The following code implements this algorithm in JavaScript:

    function scheduleMeetings(meetings) {
      let sortedPersons = meetings.sort((a, b) => a.availableFrom - b.availableFrom);
      let schedule = [];

      for (let i = 0; i < sortedPersons.length; i++) {
        let person = sortedPersons[i];
        let timeSlot = findAvailableTimeSlot(person.availableFrom, person.availableTo, schedule);
        if (timeSlot) {
          schedule.push({
            person: person.name,
            time: timeSlot
          });
        }
      }

      return schedule;
    }

    function findAvailableTimeSlot(from, to, schedule) {
      for (let i = from; i < to; i++) {
        let found = false;
        for (let j = 0; j < schedule.length; j++) {
          let existingMeeting = schedule[j];
          if (i >= existingMeeting.time && i < existingMeeting.time + existingMeeting.duration) {
            found = true;
            break;
          }
        }
        if (!found) {
          return i;
        }
      }
      return null;
    }

    let meetings = [
      { name: 'Person1', availableFrom: 9, availableTo: 11, duration: 30 },
      { name: 'Person2', availableFrom: 1, availableTo: 3, duration: 90 },
      { name: 'Person3', availableFrom: 2, availableTo: 3:30, duration: 60 }
    ];

    console.log(scheduleMeetings(meetings));

