# coding: python

import re

def main():
    sentence = input("Enter a sentence: ")
    print(capitalize(sentence))

def capitalize(sentence):
    pattern = re.compile(r"[a-z]+")
    words = pattern.findall(sentence)
    for i, word in enumerate(words):
        if i % 2 == 0:
            word = word.upper()
        words[i] = word
    return " ".join(words)

if __name__ == "__main__":
    main()

